void TrendReport(int arr[], int n) {
    if (n <= 1) {
        printf("No trend
");
        return;
    }

    int start = 0, length = 1;
    int maxStart = 0, maxLength = 1;
    int trend = 0; // 1 = increasing, -1 = decreasing, 0 = undefined

    for (int i = 1; i < n; i++) {
        int currentTrend = 0;
        if (arr[i] > arr[i - 1]) currentTrend = 1;
        else if (arr[i] < arr[i - 1]) currentTrend = -1;

        if (currentTrend == trend && trend != 0) {
            length++;
        } else {
            trend = currentTrend;
            length = 2; // current and previous
            start = i - 1;
        }

        if (length > maxLength) {
            maxLength = length;
            maxStart = start;
        }
    }

    if (maxLength < 2) {
        printf("No trend
");
        return;
    }

    for (int i = maxStart; i < maxStart + maxLength; i++) {
        printf("%d ", arr[i]);
    }
    printf("
");
}

