void TrendReport(int values[], int n) {
    if (n <= 0) {                      // invalid size
        printf("INVALID LENGTH
");
        return;
    }
    if (n == 1) {                      // single value → no movement
        printf("Start! No Trend.
");
        return;
    }

    int allUp = 1, allDown = 1;        // trend trackers
    int lastDir = 0;                   // 1 = UP, -1 = DOWN, 0 = none (e.g., equals)

    printf("Start! ");

    for (int i = 1; i < n; i++) {
        int curDir = 0;
        if (values[i] > values[i-1])   curDir = 1;
        else if (values[i] < values[i-1]) curDir = -1;
        else                            curDir = 0;   // equal

        // update overall trend flags
        if (curDir == 1)       allDown = 0;
        else if (curDir == -1) allUp   = 0;
        else { allUp = 0; allDown = 0; }

        // print direction only when it changes
        if (curDir != 0 && curDir != lastDir) {
            printf(curDir == 1 ? "UP, " : "DOWN, ");
            lastDir = curDir;
        }
    }

    if (allUp)          printf("Increasing Trend.
");
    else if (allDown)   printf("Decreasing Trend.
");
    else                printf("No Trend.
");
}
