/* Prints what "trend" the array has under several definitions,
   and also the longest non-strict (ties -> earliest) segments. */
void TrendReport(int arr[], int n)
{
    int i;

    /* ---- Whole-array trend (strict / non-strict / constant) ---- */
    int strict_inc = 1, strict_dec = 1, all_eq = 1;
    int nondec = 1, noninc = 1;

    for (i = 0; i + 1 < n; ++i) {
        if (!(arr[i] <  arr[i+1])) strict_inc = 0;
        if (!(arr[i] >  arr[i+1])) strict_dec = 0;
        if (arr[i] != arr[i+1])    all_eq     = 0;
        if (!(arr[i] <= arr[i+1])) nondec     = 0;
        if (!(arr[i] >= arr[i+1])) noninc     = 0;
    }

    printf("[Whole array]
");
    printf("  strict: ");
    if (n <= 1 || all_eq)         printf("constant
");
    else if (strict_inc)          printf("increasing
");
    else if (strict_dec)          printf("decreasing
");
    else                          printf("none
");

    printf("  non-strict: ");
    if (n <= 1 || all_eq)         printf("constant
");
    else if (nondec)              printf("non-decreasing
");
    else if (noninc)              printf("non-increasing
");
    else                          printf("none
");

    /* ---- Longest segments (non-strict) ---- */
    int bestIncL = 0, bestIncR = 0, curL, curR;
    if (n > 0) {
        curL = 0;
        for (curR = 0; curR + 1 < n; ++curR) {
            if (arr[curR] <= arr[curR+1]) { /* extend */ }
            else {
                if (curR - curL > bestIncR - bestIncL) { bestIncL = curL; bestIncR = curR; }
                curL = curR + 1;
            }
        }
        if (curR - curL > bestIncR - bestIncL) { bestIncL = curL; bestIncR = curR; }
    }

    int bestDecL = 0, bestDecR = 0;
    if (n > 0) {
        curL = 0;
        for (curR = 0; curR + 1 < n; ++curR) {
            if (arr[curR] >= arr[curR+1]) { /* extend */ }
            else {
                if (curR - curL > bestDecR - bestDecL) { bestDecL = curL; bestDecR = curR; }
                curL = curR + 1;
            }
        }
        if (curR - curL > bestDecR - bestDecL) { bestDecL = curL; bestDecR = curR; }
    }

    int bestEqL = 0, bestEqR = 0;
    if (n > 0) {
        curL = 0;
        for (curR = 0; curR + 1 < n; ++curR) {
            if (arr[curR] == arr[curR+1]) { /* extend */ }
            else {
                if (curR - curL > bestEqR - bestEqL) { bestEqL = curL; bestEqR = curR; }
                curL = curR + 1;
            }
        }
        if (curR - curL > bestEqR - bestEqL) { bestEqL = curL; bestEqR = curR; }
    }

    int lenInc = (n==0) ? 0 : (bestIncR - bestIncL + 1);
    int lenDec = (n==0) ? 0 : (bestDecR - bestDecL + 1);
    int lenEq  = (n==0) ? 0 : (bestEqR  - bestEqL  + 1);

    printf("[Longest segments (non-strict)]
");
    printf("  increasing : [%d, %d], len=%d
", bestIncL, bestIncR, lenInc);
    printf("  decreasing : [%d, %d], len=%d
", bestDecL, bestDecR, lenDec);
    printf("  constant   : [%d, %d], len=%d
", bestEqL,  bestEqR,  lenEq);

    /* ---- Best among the three (ties -> earliest) ---- */
    {
        int bestType = 1; /* 1 inc, 2 dec, 3 const */
        int bestL = bestIncL, bestR = bestIncR, bestLen = lenInc;

        if (lenDec > bestLen || (lenDec == bestLen && bestDecL < bestL)) {
            bestType = 2; bestL = bestDecL; bestR = bestDecR; bestLen = lenDec;
        }
        if (lenEq  > bestLen || (lenEq  == bestLen && bestEqL  < bestL)) {
            bestType = 3; bestL = bestEqL;  bestR = bestEqR;  bestLen = lenEq;
        }

        printf("[Best (non-strict, ties -> earliest)] ");
        if (bestType == 1) printf("increasing ");
        else if (bestType == 2) printf("decreasing ");
        else                  printf("constant   ");
        printf("[%d, %d], len=%d
", bestL, bestR, bestLen);
    }
}

