#include <stdio.h>

void TrendReport(int values[], int n) {
    if (n <= 0) { printf("INVALID LENGTH"); return; }
    if (n == 1) { printf("Start! No Trend."); return; }
    if (n == 2) {
        if (values[1] > values[0])      printf("Start! UP, Increasing Trend.");
        else if (values[1] < values[0]) printf("Start! DOWN, Decreasing Trend.");
        else                             printf("Start! No Trend.");
        return;
    }

    int dir = 0; // +1 inc, -1 dec, 0 all equal so far
    for (int i = 1; i < n; i++) {
        if (values[i] > values[i-1]) { dir = +1; break; }
        if (values[i] < values[i-1]) { dir = -1; break; }
    }

    if (dir == 0) { printf("constant"); return; }

    for (int i = 1; i < n; i++) {
        if ((dir == +1 && values[i] <= values[i-1]) ||
            (dir == -1 && values[i] >= values[i-1])) {
            printf("no trend");
            return;
        }
    }

    printf(dir == +1 ? "increasing" : "decreasing");
}
